#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353;

long long power(long long base, int exponent) {
    if (exponent == 0) return 1;
    long long half = power(base, exponent / 2);
    long long result = (half * half) % MOD;
    if (exponent % 2 == 1) {
        result = (result * base) % MOD;
    }
    return result;
}

vector<vector<long long>> multiplyMatrices(const vector<vector<long long>>& a, const vector<vector<long long>>& b) {
    int rowsA = a.size(), colsA = a[0].size();
    int rowsB = b.size(), colsB = b[0].size();
    vector<vector<long long>> result(rowsA, vector<long long>(colsB, 0));
    for (int i = 0; i < rowsA; i++) {
        for (int j = 0; j < colsB; j++) {
            long long sum = 0;
            for (int k = 0; k < colsA; k++) {
                sum += a[i][k] * b[k][j];
            }
            result[i][j] = sum % MOD;
        }
    }
    return result;
}

vector<vector<long long>> matrixPower(const vector<vector<long long>>& base, int exponent) {
    if (exponent == 1) return base;
    vector<vector<long long>> half = matrixPower(base, exponent / 2);
    vector<vector<long long>> result = multiplyMatrices(half, half);
    if (exponent % 2 == 1) {
        result = multiplyMatrices(result, base);
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m, l, r;
    cin >> n >> m >> l >> r;

    if (n % 2 == 1 && m % 2 == 1) {
        long long result = power(power(r - l + 1, n), m);
        cout << result << "\n";
        return 0;
    }

    int evenCount = r / 2 - (l + 1) / 2 + 1;
    int oddCount = (r - l + 1) - evenCount;

    vector<vector<long long>> matrix = {{evenCount, oddCount}, {oddCount, evenCount}};
    matrix = matrixPower(matrix, n);
    matrix = matrixPower(matrix, m);
    cout << matrix[0][0] << "\n";

    return 0;
}
